package com.nigson.integration.notification;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import com.nigson.integration.platform.AuditWriter;
import com.nigson.integration.providers.TwilioAccount;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.PrivateWorkload;
import com.nigson.shared.security.ActorAssertion;
import io.micrometer.core.instrument.MeterRegistry;

/** Durable owner-local signed callback ledger and monotonic notification outcome projection. */
public final class NotificationReceiptService {
 private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final AuditWriter audit;private final Clock clock;private final MeterRegistry metrics;
 public NotificationReceiptService(JdbcTemplate jdbc,PlatformTransactionManager manager,AuditWriter audit,Clock clock,MeterRegistry metrics){this.jdbc=jdbc;tx=new TransactionTemplate(manager);tx.setTimeout(5);this.audit=audit;this.clock=clock;this.metrics=metrics;}
 public boolean receive(PrivateWorkload.Proof proof,NotificationReceiptValues r,UUID correlation){var route=PrivateWorkload.ROUTES.stream().filter(v->v.api().equals("API-189")&&v.owner().equals("integration")&&v.client().equals("nigson-commerce")).findFirst().orElseThrow(ActorAssertion::denied);if(proof==null||proof.actor()!=null||!route.equals(proof.route())||!proof.client().equals(route.client())||correlation==null||r==null||r.receivedAt().isAfter(clock.instant().plusSeconds(30)))throw ActorAssertion.denied();return Boolean.TRUE.equals(tx.execute(status->{jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");var jobs=jdbc.queryForList("SELECT * FROM integration.notification_job WHERE id=? FOR UPDATE",r.jobId());var dispatches=jdbc.queryForList("SELECT * FROM integration.notification_dispatch WHERE id=? FOR UPDATE",r.jobId());if(jobs.size()!=1||dispatches.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var j=jobs.getFirst();var d=dispatches.getFirst();String identity;try{identity=TwilioAccount.fingerprint(ProviderMode.value((String)j.get("provider_mode")),(String)d.get("account_sid"),(String)d.get("messaging_service_sid"));}catch(RuntimeException invalid){throw rule();}boolean verification="CONTACT_VERIFICATION".equals(j.get("template_code"))&&d.get("command_hash")==null&&d.get("recipient_ciphertext")==null&&d.get("variables_ciphertext")==null&&d.get("context_key_revision")==null&&d.get("context_basis")==null;boolean staff="STAFF_LEAD_REPLY".equals(j.get("template_code"))&&"WHATSAPP".equals(j.get("channel"))&&d.get("command_hash")!=null&&d.get("recipient_ciphertext")!=null&&d.get("variables_ciphertext")!=null&&d.get("context_key_revision")!=null&&d.get("context_basis")!=null;if(!"experience".equals(j.get("owner_service"))||!Set.of("SMS","WHATSAPP").contains(j.get("channel"))||!"TRANSACTIONAL".equals(j.get("classification"))||!(verification||staff)||!r.accountSid().equals(d.get("account_sid"))||!identity.equals(d.get("account_hash")))throw rule();
   String saved=(String)d.get("provider_message_id"),jobSid=(String)j.get("provider_reference"),stage=(String)d.get("stage");if(saved!=null&&!saved.equals(r.messageSid())||jobSid!=null&&!jobSid.equals(r.messageSid()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);boolean firstBinding=saved==null&&jobSid==null&&Set.of("SUBMITTING","UNKNOWN").contains(stage)&&d.get("request_hash")!=null&&d.get("submitted_at")!=null&&((Number)d.get("attempt_count")).intValue()==1;if(saved==null&&!firstBinding)throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);if(!Set.of("ACCEPTED","UNKNOWN","FAILED").contains(stage)&&!firstBinding)throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);
   var bound=jdbc.queryForList("SELECT id FROM integration.notification_dispatch WHERE account_sid=? AND provider_message_id=?",r.accountSid(),r.messageSid());if(bound.stream().anyMatch(row->!r.jobId().toString().equals(row.get("id").toString())))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);int inserted=jdbc.update("INSERT INTO integration.message_receipt(id,created_by,job_id,provider,provider_message_id,event_hash,provider_status,received_at,error_code) VALUES (?,'twilio-status-callback',?,'TWILIO',?,?,?,?,?) ON CONFLICT (provider,provider_message_id,event_hash) DO NOTHING",EventCodec.uuid7(clock.instant()),r.jobId(),r.messageSid(),r.eventHash(),r.status(),Timestamp.from(r.receivedAt()),r.errorCode());if(inserted==0){var prior=jdbc.queryForList("SELECT job_id,provider_status FROM integration.message_receipt WHERE provider='TWILIO' AND provider_message_id=? AND event_hash=?",r.messageSid(),r.eventHash());if(prior.size()!=1||!r.jobId().toString().equals(prior.getFirst().get("job_id").toString())||!r.status().equals(prior.getFirst().get("provider_status")))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);return true;}
   String current=(String)j.get("state"),next=nextState(current,r.status());boolean terminal=Set.of("DELIVERED","FAILED","SUPPRESSED").contains(current);String finalSid=saved==null?r.messageSid():saved;String finalStage=terminal?stage:next.equals("FAILED")?"FAILED":next.equals("DELIVERED")?"ACCEPTED":"ACCEPTED";if(!terminal||saved==null){jdbc.update("UPDATE integration.notification_job SET state=?,provider_reference=?,lease_until=NULL,version=version+1,updated_at=?,updated_by='twilio-status-callback' WHERE id=?",terminal?current:next,finalSid,Timestamp.from(clock.instant()),r.jobId());jdbc.update("UPDATE integration.notification_dispatch SET stage=?,provider_message_id=?,lease_until=NULL,error_code=?,version=version+1,updated_at=?,updated_by='twilio-status-callback' WHERE id=?",terminal?stage:finalStage,finalSid,r.errorCode(),Timestamp.from(clock.instant()),r.jobId());}
   audit.append("twilio-status-callback",AuditValues.ActorKind.SERVICE,AuditValues.Action.NOTIFICATION_DELIVERY,AuditValues.Resource.NOTIFICATION,r.jobId(),correlation,AuditValues.Reason.VERIFIED_PROVIDER,null,Map.of("state",terminal?current:next,"channel",(String)j.get("channel")),null);String metric=terminal?current:next;org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.notification.receipts","state",metric).increment();}});return true;}));}
 private static String nextState(String current,String provider){if(Set.of("DELIVERED","FAILED","SUPPRESSED").contains(current))return current;if(Set.of("delivered","read").contains(provider))return "DELIVERED";if(Set.of("failed","undelivered","canceled").contains(provider))return "FAILED";if(Set.of("SENT","UNKNOWN","CLAIMED").contains(current))return "SENT";throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);}
 private static Problem.Failure rule(){return new Problem.Failure(ProblemCode.NOTIFICATION_RULE_VIOLATION);}
 private static final class ProviderMode {static com.nigson.shared.security.ProviderHttp.Mode value(String mode){return switch(mode){case "MOCK"->com.nigson.shared.security.ProviderHttp.Mode.MOCK;case "SANDBOX"->com.nigson.shared.security.ProviderHttp.Mode.TEST;case "LIVE"->com.nigson.shared.security.ProviderHttp.Mode.LIVE;default->throw rule();};}}
}
